{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-poYjnF/src/model.js","content":"/**
 * Data model for a parsed configuration document.
 *
 * A `TomlTable` backs both `[header]` tables and inline `{ }` tables. Its
 * `path` is the dotted key path from the document root, used to build the
 * `<path>` portion of error messages, and `headerDefined` records whether a
 * `[name]` header (not a dotted key or an implicit walk) made this exact
 * table current, which is what a second `[name]` header for the same path
 * is not allowed to repeat.
 *
 * `TomlArray` backs `[ ]` array values. `TomlAoT` backs the array produced
 * by repeating a `[[name]]` header; each of its items is a `TomlTable`.
 *
 * Scalars are plain objects `{ t, v }` where `t` is one of `string`,
 * `integer`, `float`, `boolean`; integers carry a `BigInt` value so large
 * values print without loss of precision.
 */

export class TomlTable {
  constructor() {
    this.entries = new Map();
    this.headerDefined = false;
    this.path = [];
  }
}

export class TomlArray {
  constructor() {
    this.items = [];
    this.path = [];
  }
}

export class TomlAoT {
  constructor() {
    this.items = [];
    this.path = [];
  }
}

export class CliError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`);
    this.line = line;
    this.reason = reason;
  }
}
"}

