{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-poYjnF/src/parser.js","content":"/**
 * Parser for the configuration document format: line-oriented, TOML-like,
 * with headers, dotted keys, and a small value grammar. Every directive
 * fits on one line, so the whole parser works line by line.
 */

import { TomlTable, TomlArray, TomlAoT, CliError } from './model.js'

const KEY_CHAR = /[A-Za-z0-9_-]/
const DIGITS = '[0-9](_?[0-9])*'
const INT_BODY = `[+-]?${DIGITS}`
const FRAC = `\\.${DIGITS}`
const EXP = `[eE][+-]?${DIGITS}`
const INT_RE = new RegExp(`^${INT_BODY}$`)
const FLOAT_RE = new RegExp(`^${INT_BODY}(?:${FRAC}${EXP}|${FRAC}|${EXP})$`)
const BAREWORD_STOP = new Set([' ', '\t', ',', ']', '}'])

class Scanner {
  constructor(line, lineNo) {
    this.s = line
    this.i = 0
    this.lineNo = lineNo
  }

  peek() {
    return this.s[this.i]
  }

  eof() {
    return this.i >= this.s.length
  }

  skipWS() {
    while (!this.eof() && (this.s[this.i] === ' ' || this.s[this.i] === '\t')) this.i++
  }

  err(reason) {
    throw new CliError(this.lineNo, reason)
  }
}

function commentOrEnd(sc) {
  return sc.eof() || sc.peek() === '#' || sc.peek() === ';'
}

function checkLineEnd(sc, reason) {
  sc.skipWS()
  if (commentOrEnd(sc)) return
  sc.err(reason)
}

function parseBasicStringRaw(sc) {
  sc.i++ // opening "
  let out = ''
  for (;;) {
    if (sc.eof()) sc.err('unterminated string')
    const c = sc.s[sc.i]
    if (c === '"') {
      sc.i++
      return out
    }
    if (c === '\\') {
      sc.i++
      if (sc.eof()) sc.err('unterminated string')
      const e = sc.s[sc.i]
      if (e === '"') { out += '"'; sc.i++ }
      else if (e === '\\') { out += '\\'; sc.i++ }
      else if (e === 'n') { out += '\n'; sc.i++ }
      else if (e === 't') { out += '\t'; sc.i++ }
      else if (e === 'r') { out += '\r'; sc.i++ }
      else if (e === '0') { out += '\0'; sc.i++ }
      else if (e === 'u') {
        sc.i++
        const hex = sc.s.slice(sc.i, sc.i + 4)
        if (hex.length < 4) sc.err('unterminated string')
        if (!/^[0-9a-fA-F]{4}$/.test(hex)) sc.err('invalid escape \\u')
        out += String.fromCharCode(parseInt(hex, 16))
        sc.i += 4
      } else {
        sc.err(`invalid escape \\${e}`)
      }
    } else {
      out += c
      sc.i++
    }
  }
}

function parseLiteralStringRaw(sc) {
  sc.i++ // opening '
  const start = sc.i
  for (;;) {
    if (sc.eof()) sc.err('unterminated string')
    if (sc.s[sc.i] === "'") {
      const out = sc.s.slice(start, sc.i)
      sc.i++
      return out
    }
    sc.i++
  }
}

function parseName(sc) {
  if (sc.eof()) sc.err('expected a name')
  const c = sc.peek()
  if (c === '"') return parseBasicStringRaw(sc)
  if (c === "'") return parseLiteralStringRaw(sc)
  if (KEY_CHAR.test(c)) {
    const start = sc.i
    while (!sc.eof() && KEY_CHAR.test(sc.peek())) sc.i++
    return sc.s.slice(start, sc.i)
  }
  sc.err('expected a name')
}

function parseDottedName(sc) {
  const names = []
  for (;;) {
    sc.skipWS()
    names.push(parseName(sc))
    sc.skipWS()
    if (sc.peek() === '.') {
      sc.i++
      continue
    }
    break
  }
  return names
}

function parseBarewordValue(sc) {
  const start = sc.i
  while (!sc.eof() && !BAREWORD_STOP.has(sc.peek())) sc.i++
  const text = sc.s.slice(start, sc.i)
  if (text === 'true') return { t: 'boolean', v: true }
  if (text === 'false') return { t: 'boolean', v: false }
  if (INT_RE.test(text)) {
    return { t: 'integer', v: BigInt(text.replace(/_/g, '')) }
  }
  if (FLOAT_RE.test(text)) {
    return { t: 'float', v: Number(text.replace(/_/g, '')) }
  }
  sc.err(`invalid value ${text}`)
}

function parseValue(sc, path) {
  sc.skipWS()
  if (sc.eof() || sc.peek() === '#' || sc.peek() === ';' ||
      sc.peek() === ',' || sc.peek() === ']' || sc.peek() === '}') {
    sc.err('expected a value')
  }
  const c = sc.peek()
  if (c === '"') return { t: 'string', v: parseBasicStringRaw(sc) }
  if (c === "'") return { t: 'string', v: parseLiteralStringRaw(sc) }
  if (c === '[') return parseArray(sc, path)
  if (c === '{') return parseInlineTable(sc, path)
  return parseBarewordValue(sc)
}

function parseArray(sc, path) {
  sc.i++ // consume [
  const arr = new TomlArray()
  arr.path = path.slice()
  sc.skipWS()
  if (sc.peek() === ']') {
    sc.i++
    return arr
  }
  for (;;) {
    const val = parseValue(sc, path)
    arr.items.push(val)
    sc.skipWS()
    if (commentOrEnd(sc)) sc.err('unterminated array')
    const c = sc.peek()
    if (c === ',') {
      sc.i++
      sc.skipWS()
      if (sc.peek() === ']') {
        sc.i++
        return arr
      }
      continue
    }
    if (c === ']') {
      sc.i++
      return arr
    }
    sc.err('unterminated array')
  }
}

function parseInlineTable(sc, path) {
  sc.i++ // consume {
  const tbl = new TomlTable()
  tbl.path = path.slice()
  sc.skipWS()
  if (sc.peek() === '}') {
    sc.i++
    return tbl
  }
  for (;;) {
    sc.skipWS()
    const names = parseDottedName(sc)
    sc.skipWS()
    if (sc.peek() !== '=') sc.err('expected = in an inline table')
    sc.i++
    sc.skipWS()
    const fullPath = path.concat(names)
    const val = parseValue(sc, fullPath)
    assignDottedKey(tbl, names, path, val, sc.lineNo)
    sc.skipWS()
    if (commentOrEnd(sc)) sc.err('unterminated inline table')
    const c = sc.peek()
    if (c === ',') {
      sc.i++
      continue
    }
    if (c === '}') {
      sc.i++
      return tbl
    }
    sc.err('unterminated inline table')
  }
}

/**
 * Walk `names` from `container`, creating tables along the way, and return
 * the table the last name should be resolved against. `path` is the path
 * of `container` itself, used to build error messages.
 */
function walkTables(container, names, path, lineNo) {
  let cur = container
  const curPath = path.slice()
  for (const name of names) {
    curPath.push(name)
    if (cur.entries.has(name)) {
      const v = cur.entries.get(name)
      if (v instanceof TomlTable) {
        cur = v
      } else if (v instanceof TomlAoT) {
        cur = v.items[v.items.length - 1]
      } else {
        throw new CliError(lineNo, `${curPath.join('.')} is not a table`)
      }
    } else {
      const nt = new TomlTable()
      nt.path = curPath.slice()
      cur.entries.set(name, nt)
      cur = nt
    }
  }
  return cur
}

function assignDottedKey(container, names, path, valueNode, lineNo) {
  const parent = walkTables(container, names.slice(0, -1), path, lineNo)
  const last = names[names.length - 1]
  const fullPath = path.concat(names)
  if (parent.entries.has(last)) {
    throw new CliError(lineNo, `key ${fullPath.join('.')} is defined twice`)
  }
  parent.entries.set(last, valueNode)
}

function processHeader(root, names, isArray, lineNo) {
  const parent = walkTables(root, names.slice(0, -1), [], lineNo)
  const last = names[names.length - 1]
  const fullPath = names

  if (!isArray) {
    if (parent.entries.has(last)) {
      const v = parent.entries.get(last)
      if (!(v instanceof TomlTable)) {
        throw new CliError(lineNo, `${fullPath.join('.')} is not a table`)
      }
      if (v.headerDefined) {
        throw new CliError(lineNo, `table ${fullPath.join('.')} is defined twice`)
      }
      v.headerDefined = true
      return v
    }
    const nt = new TomlTable()
    nt.path = fullPath.slice()
    nt.headerDefined = true
    parent.entries.set(last, nt)
    return nt
  }

  if (parent.entries.has(last)) {
    const v = parent.entries.get(last)
    if (!(v instanceof TomlAoT)) {
      throw new CliError(lineNo, `${fullPath.join('.')} is not an array of tables`)
    }
    const nt = new TomlTable()
    nt.path = fullPath.slice()
    nt.headerDefined = true
    v.items.push(nt)
    return nt
  }
  const aot = new TomlAoT()
  aot.path = fullPath.slice()
  const nt = new TomlTable()
  nt.path = fullPath.slice()
  nt.headerDefined = true
  aot.items.push(nt)
  parent.entries.set(last, aot)
  return nt
}

function parseHeaderLine(sc, root) {
  sc.i++ // consume first [
  let isArray = false
  if (sc.peek() === '[') {
    isArray = true
    sc.i++
  }
  const names = parseDottedName(sc)
  sc.skipWS()
  if (sc.peek() !== ']') sc.err('unterminated table header')
  sc.i++
  if (isArray) {
    if (sc.peek() !== ']') sc.err('unterminated table header')
    sc.i++
  }
  checkLineEnd(sc, 'trailing text after a table header')
  return processHeader(root, names, isArray, sc.lineNo)
}

function parseKeyValueLine(sc, current) {
  const names = parseDottedName(sc)
  sc.skipWS()
  if (commentOrEnd(sc) || sc.peek() !== '=') sc.err('expected key = value')
  sc.i++
  sc.skipWS()
  const fullPath = current.path.concat(names)
  const val = parseValue(sc, fullPath)
  checkLineEnd(sc, 'trailing text after a value')
  assignDottedKey(current, names, current.path, val, sc.lineNo)
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = new TomlTable()
  let current = root

  for (let idx = 0; idx < lines.length; idx++) {
    const lineNo = idx + 1
    const sc = new Scanner(lines[idx], lineNo)
    sc.skipWS()
    if (sc.eof()) continue
    const c = sc.peek()
    if (c === '#' || c === ';') continue
    if (c === '[') {
      current = parseHeaderLine(sc, root)
      continue
    }
    parseKeyValueLine(sc, current)
  }

  return root
}
"}

