      cur.entries.set(name, nt)
      cur = nt
    }
  }
  return cur
}

function assignDottedKey(container, names, path, valueNode, lineNo) {
  const parent = walkTables(container, names.slice(0, -1), path, lineNo)
  const last = names[names.length - 1]
  const fullPath = path.concat(names)
  if (parent.entries.has(last)) {
    throw new CliError(lineNo, `key ${fullPath.join('.')} is defined twice`)
  }
  parent.entries.set(last, valueNode)
}

function processHeader(root, names, isArray, lineNo) {
  const parent = walkTables(root, names.slice(0, -1), [], lineNo)
  const last = names[names.length - 1]
  const fullPath = names

  if (!isArray) {
    if (parent.entries.has(last)) {
      const v = parent.entries.get(last)
      if (!(v instanceof TomlTable)) {
        throw new CliError(lineNo, `${fullPath.join('.')} is not a table`)
      }
      if (v.headerDefined) {
        throw new CliError(lineNo, `table ${fullPath.join('.')} is defined twice`)
      }
      v.headerDefined = true
      return v
    }
    const nt = new TomlTable()
    nt.path = fullPath.slice()
    nt.headerDefined = true
    parent.entries.set(last, nt)
    return nt
  }

  if (parent.entries.has(last)) {
    const v = parent.entries.get(last)
    if (!(v instanceof TomlAoT)) {
      throw new CliError(lineNo, `${fullPath.join('.')} is not an array of tables`)
    }
    const nt = new TomlTable()
    nt.path = fullPath.slice()
    nt.headerDefined = true
    v.items.push(nt)
    return nt
  }
  const aot = new TomlAoT()
  aot.path = fullPath.slice()
  const nt = new TomlTable()
  nt.path = fullPath.slice()
  nt.headerDefined = true
  aot.items.push(nt)
  parent.entries.set(last, aot)
  return nt
}

function parseHeaderLine(sc, root) {
  sc.i++ // consume first [
  let isArray = false
  if (sc.peek() === '[') {
    isArray = true
    sc.i++
  }
  const names = parseDottedName(sc)
  sc.skipWS()
  if (sc.peek() !== ']') sc.err('unterminated table header')
  sc.i++
  if (isArray) {
    if (sc.peek() !== ']') sc.err('unterminated table header')
    sc.i++
  }
  checkLineEnd(sc, 'trailing text after a table header')
  return processHeader(root, names, isArray, sc.lineNo)
}

function parseKeyValueLine(sc, current) {
  const names = parseDottedName(sc)
  sc.skipWS()
  if (commentOrEnd(sc) || sc.peek() !== '=') sc.err('expected key = value')
  sc.i++
  sc.skipWS()
  const fullPath = current.path.concat(names)
  const val = parseValue(sc, fullPath)
  checkLineEnd(sc, 'trailing text after a value')
  assignDottedKey(current, names, current.path, val, sc.lineNo)
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = new TomlTable()
  let current = root

  for (let idx = 0; idx < lines.length; idx++) {
    const lineNo = idx + 1
    const sc = new Scanner(lines[idx], lineNo)
    sc.skipWS()
    if (sc.eof()) continue
    const c = sc.peek()
    if (c === '#' || c === ';') continue
    if (c === '[') {
      current = parseHeaderLine(sc, root)
      continue
    }
    parseKeyValueLine(sc, current)
  }

  return root
}
"}

