  switch (node.t) {
    case 'string': return JSON.stringify(node.v)
    case 'boolean': return node.v ? 'true' : 'false'
    case 'integer': return node.v.toString()
    case 'float': return JSON.stringify(node.v)
    default: throw new Error(`unreachable scalar type ${node.t}`)
  }
}

