  if (node instanceof TomlTable) return jsonTable(node, indent)
  if (node instanceof TomlArray || node instanceof TomlAoT) return jsonArray(node.items, indent)
  return jsonScalar(node)
}

function jsonTable(tbl, indent) {
  const keys = Array.from(tbl.entries.keys()).sort(compareCodePoint)
  if (keys.length === 0) return '{}'
  const pad = '  '.repeat(indent + 1)
  const closePad = '  '.repeat(indent)
  const parts = keys.map(k => `${pad}${JSON.stringify(k)}: ${jsonValue(tbl.entries.get(k), indent + 1)}`)
  return `{\n${parts.join(',\n')}\n${closePad}}`
}

function jsonArray(items, indent) {
  if (items.length === 0) return '[]'
  const pad = '  '.repeat(indent + 1)
  const closePad = '  '.repeat(indent)
  const parts = items.map(it => `${pad}${jsonValue(it, indent + 1)}`)
  return `[\n${parts.join(',\n')}\n${closePad}]`
}

export function toJSON(root) {
  return `${jsonValue(root, 0)}\n`
}

function emitKeys(node, path, out) {
  if (node instanceof TomlTable) {
    const keys = Array.from(node.entries.keys()).sort(compareCodePoint)
    for (const k of keys) {
      const child = node.entries.get(k)
      const childPath = path === '' ? k : `${path}.${k}`
      out.push(`${childPath} ${typeOf(child)}`)
