/**
 * An inline table literal is closed as soon as it finishes parsing: every
 * table it contains, including ones dotted keys built inside it, becomes
 * unreachable to later headers and dotted keys.
 */
function freezeDeep(node) {
  if (node instanceof TomlTable) {
    node.frozen = true
    for (const v of node.entries.values()) freezeDeep(v)
  } else if (node instanceof TomlArray) {
    for (const item of node.items) freezeDeep(item)
  }
}"}

